WHERE t.warehouse_id IN
#{warehouseId}
AND t.company_id = #{bo.companyId}
AND t.warehouse_id = #{bo.warehouseId}
AND l.zone_id = #{bo.zoneId}
AND t.location_id = #{bo.locationId}
AND m.material_code LIKE CONCAT('%', #{bo.materialCode}, '%')
AND m.material_name LIKE CONCAT('%', #{bo.materialName}, '%')
AND t.transaction_type = #{bo.transactionType}
AND t.source_type = #{bo.sourceType}
AND t.source_no LIKE CONCAT('%', #{bo.sourceNo}, '%')
AND t.occurred_at >= #{bo.beginOccurredAt}
AND t.occurred_at <= #{bo.endOccurredAt}
